function CountDigits(s: string): int
    reads s
    ensures 0 <= CountDigits(s) <= length(s)
{
    var count := 0;
    var i := 0;
    while (i < length(s))
        invariant 0 <= i <= length(s)
        invariant count == CountDigits(Substring(s, 0, i))
    {
        if (s[i] >= '0' && s[i] <= '9') {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function ContainsExactlyOneDot(s: string): bool
