            dotCount := dotCount + 1;
        }
        i := i + 1;
    }
    return dotCount == 1;
}

function SubstringBeforeDotIsValid(s: string): bool
    reads s
{
    var dotIndex := IndexOfDot(s);
    return dotIndex > 0 && (s[0] >= 'a' && s[0] <= 'z' || s[0] >= 'A' && s[0] <= 'Z');
}

function SubstringAfterDotIsValid(s: string): bool
    reads s
{
    var dotIndex := IndexOfDot(s);
    if (dotIndex == -1 || dotIndex == length(s) - 1) {
        return false;
    }
    var extension := Substring(s, dotIndex + 1, length(s) - dotIndex - 1);
    return extension == "txt" || extension == "exe" || extension == "dll";
}

function IndexOfDot(s: string): int
    reads s
{
    var i := 0;
    while (i < length(s))
        invariant 0 <= i <= length(s)
    {
        if (s[i] == '.') {
            return i;
        }
        i := i + 1;
    }
    return -1; // Indicate no dot found
}

